package com.magneticraft2.common.systems.Multiblocking.core;

import net.minecraft.core.Direction;

/**
 * Selects a shared baked model by canonical south-facing cell location.
 * Does no geometry construction at render time. Referenced resources are
 * generated by tools/bronze-bloomery/generate-models.mjs.
 */
public final class BloomeryModelParts {
    private BloomeryModelParts() {}

    public static String key(Direction facing, int dx, int dy, int dz, boolean wasAir) {
        // Rotate world offset back into the SOUTH canonical coordinate frame.
        int cx = switch (facing) {
            case WEST -> dz;
            case NORTH -> -dx;
            case EAST -> -dz;
            default -> dx;
        };
        int cz = switch (facing) {
            case WEST -> -dx;
            case NORTH -> -dz;
            case EAST -> dx;
            default -> dz;
        };
        int x = cx + 2, z = cz + 4;
        String part;
        if (wasAir) {
            part = "hearth";
        } else if (dy == 0) {
            part = "foundation";
        } else if (dy == 1 || dy == 2) {
            String tier = dy == 1 ? "lower_" : "upper_";
            if (dy == 1 && x == 0 && z == 2) part = "tuyere";
            else if (z == 4 && x == 2) part = "upper_arch";
            else if (z == 4 && (x == 0 || x == 4))
                part = tier + (x == 0 ? "corner_left" : "corner_right");
            else if (z == 4 && (x == 1 || x == 3))
                part = tier + (x == 1 ? "jamb_left" : "jamb_right");
            else part = tier + "wall";
        } else if (dy == 3) {
            part = (z == 3 && x == 2) ? "shoulder_front" : "shoulder";
        } else {
            part = (z == 3 && x == 2) ? "chimney_front" : "chimney";
        }
        return "bloomery_furnace_" + facing.getName() + "/" + part;
    }
}
